INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
(3,'Đi','Tay phải giống chữ cái ngón tay "V", lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đặt trước ngực, đưa tay về phía trước đồng thời cử động 2 ngón tay lần lượt ra – vào.','/images/signs/sign_p0083_1.png','đi,walk,hoạt động',78),
(3,'Đứng','Tay trái duỗi thẳng, khép kín, lòng bàn tay hướng lên trên, đầu các ngón tay hướng ra ngoài. Tay phải giống chữ cái ngón tay "V", lòng bàn tay hướng vào trong, đầu các ngón tay đặt lên lòng bàn tay trái.','/images/signs/sign_p0083_2.png','đứng,stand,hoạt động',79),
(3,'Ngồi','Tay trái giống chữ cái ngón tay "U", lòng bàn tay úp, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải giống chữ cái ngón tay "V", lòng bàn tay úp, đầu ngón tay hướng xuống dưới, ôm lấy ngón trỏ và ngón giữa tay trái.','/images/signs/sign_p0083_3.png','ngồi,sit,hoạt động',80),
(3,'Nằm','Hai tay khép, lòng bàn tay hướng về phía trước, đặt chống vào nhau, áp vào sau gáy, đầu hơi ngả ra phía sau.','/images/signs/sign_p0083_4.png','nằm,lie down,hoạt động',81),
(3,'Bò','Hai tay xoè, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song trước ngực, di chuyển lần lượt từng tay tiến ra phía trước (lặp lại hai lần).','/images/signs/sign_p0084_1.png','bò,crawl,hoạt động',82),
(3,'Lấy','Tay trái khép, lòng bàn tay ngửa, đầu ngón tay hướng về phía trước, đặt trước ngực. Tay phải giống chữ cái ngón tay "V", lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt chạm vào lòng bàn tay trái, giữ nguyên cánh tay, lật cổ tay lên – xuống (lặp lại 2 lần).','/images/signs/sign_p0084_2.png','lấy,take,hoạt động',83),
(3,'Chạy','Hai tay nắm, lòng bàn tay hướng vào nhau, đặt song song trước bụng, di chuyển lần lượt hai tay ra – vào (lặp lại 2 lần).','/images/signs/sign_p0084_3.png','chạy,run,hoạt động',84),
(3,'Nhảy','Tay trái khép, lòng bàn tay ngửa, đầu ngón tay hướng về phía trước, đặt trước ngực. Tay phải giống chữ cái ngón tay "V", lòng bàn tay hướng vào trong, đầu ngón tay hướng xuống dưới, đặt chạm đầu ngón tay vào gần cổ tay trái, di chuyển theo đường vòng cung đến đầu các ngón tay trái.','/images/signs/sign_p0084_4.png','nhảy,jump,hoạt động',85),
(3,'Ngủ','Tay phải khép, hơi khum lại, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt áp vào má phải, đầu hơi ngả sang phải.','/images/signs/sign_p0085_1.png','ngủ,sleep,hoạt động',86),
(3,'Đi vệ sinh','1. Tay phải giống chữ cái ngón tay "V", lòng bàn tay úp, đầu ngón tay hướng xuống dưới, gập hai ngón tay lần lượt ra – vào và đưa tay về phía trước. 2. Ngón trỏ và ngón cái tay phải cong hình chữ cái ngón tay "C", ba ngón còn lại xoè ra, lòng bàn tay hướng ra ngoài, đặt trước ngực.','/images/signs/sign_p0085_2.png','đi vệ sinh,toilet,hoạt động',87),
(3,'Ăn','Tay phải chụm, lòng bàn tay hướng vào trong, đặt trước cổ, di chuyển tay lên sát miệng.','/images/signs/sign_p0085_3.png','ăn,eat,hoạt động',88),
(3,'Uống','Tay phải giống chữ cái ngón tay "C", lòng bàn tay hướng sang trái, đặt trước ngực, đưa tay lên sát miệng.','/images/signs/sign_p0085_4.png','uống,drink,hoạt động',89),
(3,'Chải đầu','Tay phải nắm, lòng bàn tay hướng sang trái, đặt bên phải đầu, di chuyển xuống dưới (lặp lại 2 lần).','/images/signs/sign_p0086_1.png','chải đầu,comb,hoạt động',90),
(3,'Mặc quần áo','Hai tay nắm, lòng bàn tay hướng vào trong, đặt ở hai bên vai, di chuyển đồng thời hai tay vào trong – xuống dưới.','/images/signs/sign_p0086_2.png','mặc quần áo,dress,hoạt động',91),
(3,'Tắm','Hai tay mở xoè, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang hai bên, đặt áp vào người, tay trái đặt trên, tay phải đặt dưới, di chuyển đồng thời cả hai tay sang hai bên ngược chiều nhau (lặp lại 2 – 3 lần).','/images/signs/sign_p0086_3.png','tắm,bath,hoạt động',92),
(3,'Gội đầu','Hai tay mở, khum lại, lòng bàn tay hướng vào nhau, đặt chạm các đầu ngón tay vào hai bên đầu, di chuyển các ngón tay giống động tác gội đầu.','/images/signs/sign_p0086_4.png','gội đầu,shampoo,hoạt động',93),
(3,'Rửa tay','Hai tay khép, lòng bàn tay hướng vào nhau, đặt áp vào nhau, di chuyển hai tay ngược chiều nhau (lặp lại 2 – 3 lần).','/images/signs/sign_p0086_5.png','rửa tay,wash hands,hoạt động',94),
(3,'Rửa chân','Tay trái giống chữ cái ngón tay "V", lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đặt trước ngực. Tay phải khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt chạm vào đầu ngón trỏ tay trái, di chuyển tiến lên, lùi xuống (2 lần).','/images/signs/sign_p0086_6.png','rửa chân,wash feet,hoạt động',95),
(3,'Rửa mặt','Hai tay khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt sát vào nhau, trước mặt, di chuyển đồng thời hai tay một vòng tròn quanh mặt theo chiều kim đồng hồ.','/images/signs/sign_p0087_1.png','rửa mặt,wash face,hoạt động',96),
(3,'Đánh răng','Tay phải giống số tự nhiên "1", lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt gần trước miệng, di chuyển tay qua lại (2 lần).','/images/signs/sign_p0087_2.png','đánh răng,brush teeth,hoạt động',97),
(3,'Khóc','Tay phải giống chữ cái ngón tay "B", lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt gần phía trước mắt, di chuyển tay qua lại (2 lần).','/images/signs/sign_p0087_3.png','khóc,cry,cảm xúc',98),
(3,'Cười','Tay phải giống chữ cái ngón tay "C", lòng bàn tay hướng sang trái, đặt gần khoé miệng phải, di chuyển tay qua lại (2 lần).','/images/signs/sign_p0087_4.png','cười,laugh,cảm xúc',99),
(3,'Bẩn','Tay phải khép, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt trước cổ bên phải, giữ nguyên cánh tay, gập mạnh cổ tay xuống dưới đồng thời mặt nhăn lại.','/images/signs/sign_p0087_5.png','bẩn,dirty,trạng thái',100),
(3,'Sạch','Tay phải khép, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt áp vào cánh tay trái, di chuyển mạnh tay xuống dưới và vẩy tay ra ngoài.','/images/signs/sign_p0087_6.png','sạch,clean,trạng thái',101),
(3,'Áo phông','1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Tay phải giống chữ cái ngón tay "P", lòng bàn tay hướng xuống dưới, đặt trước ngực.','/images/signs/sign_p0089_1.png','áo phông,t-shirt,trang phục',102),
(3,'Áo len','1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo và kéo nhẹ lên. 2. Hai tay giống số tự nhiên "1", lòng bàn tay hướng vào nhau, đầu ngón tay hướng về phía trước, ngón trỏ phải đặt chéo, chạm trên ngón trỏ trái, trước ngực, xoay đồng thời hai cổ tay lên xuống giống hành động đan len.','/images/signs/sign_p0089_2.png','áo len,sweater,trang phục',103),
(3,'Áo veston','Hai tay giống chữ cái ngón tay "C", lòng bàn tay hướng vào trong, đặt chạm vào giữa ngực, tay phải đặt trên tay trái, giữ nguyên tay trái, di chuyển tay phải lên trên gần cổ.','/images/signs/sign_p0089_3.png','áo veston,vest,trang phục',104),
(3,'Áo dài (chi tiết)','1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào áo kéo nhẹ lên. 2. Tay phải khép, hơi khum lại, lòng bàn tay hướng vào trong, đầu ngón tay hướng vào trong, đặt gần ngực, di chuyển tay xuống dưới đùi.','/images/signs/sign_p0089_4.png','áo dài,ao dai,trang phục',105),
(3,'Quần âu (chi tiết)','1. Tay phải nắm, ngón cái và ngón trỏ mở ra nắm nhẹ vào quần và kéo nhẹ lên. 2. Ngón cái và ngón trỏ tay phải mở ra, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt gần hai bên cạnh mũi, đưa tay xuống dưới đồng thời chạm hai ngón tay vào nhau.','/images/signs/sign_p0090_1.png','quần âu,dress pants,trang phục',106),
(3,'Quần bò (chi tiết)','1. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào quần kéo nhẹ lên. 2. Hai tay giống chữ cái ngón tay "N", lòng bàn tay hướng vào nhau, đầu ngón tay hướng về phía trước, đặt song song, trước ngực, giữ nguyên cánh tay, gập cổ tay phải lên, gập cổ tay trái xuống và ngược lại.','/images/signs/sign_p0090_2.png','quần bò,jeans,trang phục',107),
(3,'Giống nhau','Hai tay giống số tự nhiên "1", lòng bàn tay úp, đầu ngón tay hướng về trước, đặt song song trước ngực, di chuyển đồng thời cả hai tay vào giữa và chạm vào nhau.','/images/signs/sign_p0100_3.png','giống nhau,same,so sánh',108),
(3,'Khác nhau','Hai tay giống số tự nhiên "1", lòng bàn tay hướng về trước, đầu ngón tay hướng lên trên, đặt song song trước ngực, di chuyển đồng thời cả hai tay sang hai bên.','/images/signs/sign_p0100_4.png','khác nhau,different,so sánh',109),
(3,'Màu da cam','1+2. Tay phải giống chữ cái ngón tay "D", lòng bàn tay hướng sang trái, đặt trước ngực phải, sau đó thay đổi hình dạng tay giống chữ cái ngón tay "C", đặt trước ngực phải.','/images/signs/sign_p0100_2.png','màu da cam,orange,màu sắc',110),
(3,'Màu vàng','1. Tay phải giống chữ cái ngón tay "M", đặt trước ngực, giữ nguyên cánh tay, lắc cổ tay về bên phải. 2. Tay phải giống chữ cái ngón tay "V", đặt trước ngực, lắc cổ tay.','/images/signs/sign_p0100_1.png','màu vàng,yellow,màu sắc',111);
